import { databases } from "@/lib/appwrite";
import { DB_ID, COLLECTIONS } from "@/lib/appwrite";
import { Room, RoomPayload } from "@/types/room";

import { Query } from "appwrite";

export const RoomService = {
    list() {
        return databases.listDocuments<Room>(
            DB_ID,
            COLLECTIONS.ROOMS,
            [
                Query.equal("status", "OPEN"),
                Query.equal("isPublic", true),
                Query.orderDesc("createdAt"),
            ]
        );
    },

    get(roomId: string) {
        return databases.getDocument<Room>(
            DB_ID,
            COLLECTIONS.ROOMS,
            roomId
        );
    },

    create(payload: RoomPayload) {
        return databases.createDocument<Room>(
            DB_ID,
            COLLECTIONS.ROOMS,
            "unique()",
            {
                ...payload,
                status: "OPEN",
            }
        );
    },

    close(roomId: string) {
        return databases.updateDocument(
            DB_ID,
            COLLECTIONS.ROOMS,
            roomId,
            {
                status: "CLOSED",
            }
        );
    },

    open(roomId: string) {
        return databases.updateDocument(
            DB_ID,
            COLLECTIONS.ROOMS,
            roomId,
            {
                status: "OPEN",
                closedAt: null,
            }
        );
    },
};
